// @ts-check
/// <reference path="../kino.d.ts" />
// HDFull (personal, local): movies and series that HDFull hosts on captcha-free servers (vidmoly, streamtape, mixdrop, vidoza, gamovideo).
// Copies on captcha servers (powvideo, streamplay, waaw) are never listed: a title or episode with only those is left out.
//
// The plugin carries only ids and video codes (MOVIES and SERIES below, generated by build_plugin_data.py);
// everything shown (titles, posters, overviews, genres, episode names) comes live from TMDB through kino.tmdb.
//
// Refs:  m:<tmdbId>   m:i<imdbDigits> (no TMDB id known at build time: resolved live with /find)
//        s:<tmdbTvId>                 a series (episodes lists only the episodes in the index)
//        e:<tmdbTvId>:<season>:<ep>   one episode
//        c:<slot>     one video code as an alternative copy (slot = <lang><host><code>)
//        browse:<list> | browse:genre:<genreId> | browse:recent | browse:recentTv
//
// Read top to bottom: 1. texts  2. index  3. TMDB  4. rows/browse/search/details/episodes  5. resolvers  6. resolve

// ---- 1. texts ----

const T = {
  es: {
    recent: "Películas agregadas a HDFull",
    recentTv: "Series agregadas a HDFull",
    trending: "Películas en tendencia",
    trendingTv: "Series en tendencia",
    popular: "Películas populares",
    popularTv: "Series populares",
    topRated: "Películas mejor valoradas",
    topRatedTv: "Series mejor valoradas",
    nowPlaying: "Estrenos",
    genre: "Películas de",
    episode: "Episodio",
    noStreams: "Este título no tiene una copia que cargue ahora.",
    needResolver: "Para reproducir, abre HDFull desde el menú e instala el motor de reproducción que te pedirá.",
    notFound: "No encontramos ese título.",
    tmdbDown: "No se pudo consultar el catálogo. Revisa tu conexión e inténtalo de nuevo.",
    lang: { E: "Castellano", L: "Latino", S: "Subtitulado", O: "Original" },
    status: (m, s, e) => `${m} películas, ${s} series (${e} episodios)`,
  },
  en: {
    recent: "Movies added to HDFull",
    recentTv: "Series added to HDFull",
    trending: "Trending movies",
    trendingTv: "Trending series",
    popular: "Popular movies",
    popularTv: "Popular series",
    topRated: "Top rated movies",
    topRatedTv: "Top rated series",
    nowPlaying: "New releases",
    genre: "Movies:",
    episode: "Episode",
    noStreams: "This title has no copy that loads right now.",
    needResolver: "To play, open HDFull from the menu and install the playback engine it asks for.",
    notFound: "We could not find that title.",
    tmdbDown: "Could not load the catalog. Check your connection and try again.",
    lang: { E: "Spanish (Spain)", L: "Latin American Spanish", S: "Subtitled", O: "Original" },
    status: (m, s, e) => `${m} movies, ${s} series (${e} episodes)`,
  },
};
const isEs = () => kino.language !== "en";
const t = (k) => (isEs() ? T.es : T.en)[k];

function cfg(key, fallback) {
  try {
    const v = kino.config.get(key);
    return v === null || v === undefined || v === "" ? fallback : v;
  } catch { return fallback; }
}

// ---- catalog items (shard the compact strings for kino.catalog) ----

/**
 * Turn the compact movie/series strings into kino.catalog items, fragmenting a series so no item's
 * data nears the 4096-byte limit: a movie `m:<id>` (data {c:codes}), a series header `s:<tv>` (data
 * {}) and one `e:<tv>:<S>:<E>` per episode (data {c:codes}, title "tv<tv>" as a searchable token for
 * episodesOf). Also returns the "recently added" id lists in line order (the build ships newest-first).
 * @returns {{ items: {id:string,title:string,sort:number,data:object}[], recentMovies:string[], recentSeries:string[] }}
 */
// The episode-key list ("1.1,1.2,…") is ASCII, so string length == UTF-8 bytes. A show with more
// keys than this (the biggest has 978 eps / ~5.5 KB) pages them across companion items so no item's
// JSON passes kino.catalog's 4096-byte data limit.
const KEY_LEN = 3800;

/** Split episode keys into chunks whose joined length stays under KEY_LEN. */
function chunkKeys(keys) {
  const out = [];
  let cur = [], len = 0;
  for (const k of keys) {
    const add = (cur.length ? 1 : 0) + k.length;
    if (len + add > KEY_LEN && cur.length) { out.push(cur); cur = []; len = 0; }
    cur.push(k);
    len += (cur.length > 1 ? 1 : 0) + k.length;
  }
  if (cur.length) out.push(cur);
  return out;
}

export function catalogItems(movies, series) {
  const items = [];
  const recentMovies = [];
  const recentSeries = [];
  // Lines arrive newest-first (the build orders them by firstSeen descending): keep that order in the
  // recent lists directly, and mirror it in `sort` (higher = newer). No per-title date map is needed.
  let rank = 1000000;
  for (const line of String(movies || "").split("\n")) {
    const i = line.indexOf(":");
    if (i <= 0) continue;
    const id = "m:" + line.slice(0, i);
    items.push({ id, title: "", sort: rank--, data: { c: line.slice(i + 1) } });
    recentMovies.push(id);
  }
  for (const line of String(series || "").split("\n")) {
    const i = line.indexOf(":");
    if (i <= 0) continue;
    const tv = line.slice(0, i);
    const sid = "s:" + tv;
    const sort = rank--;
    const keys = [];
    const eps = [];
    for (const part of line.slice(i + 1).split(";")) {
      const eq = part.indexOf("=");
      if (eq <= 0) continue;
      const se = part.slice(0, eq);
      const dot = se.indexOf(".");
      if (dot <= 0) continue;
      keys.push(se);
      eps.push({ id: `e:${tv}:${se.slice(0, dot)}:${se.slice(dot + 1)}`, codes: part.slice(eq + 1) });
    }
    const keyStr = keys.join(",");
    if (keyStr.length <= KEY_LEN) {
      items.push({ id: sid, title: "", sort, data: { e: keyStr } });
    } else {
      const pages = chunkKeys(keys);
      items.push({ id: sid, title: "", sort, data: { n: pages.length } });
      pages.forEach((p, k) => items.push({ id: `${sid}:k${k}`, title: "", sort, data: { e: p.join(",") } }));
    }
    for (const ep of eps) items.push({ id: ep.id, title: "", sort, data: { c: ep.codes } });
    recentSeries.push(sid);
  }
  return { items, recentMovies, recentSeries };
}

// ---- catalog storage (kino.catalog + kino.storage markers) ----

const CK = {
  ver: "catVersion", at: "catAt", cursor: "catCursor", impVer: "catImportVer",
  recentM: "catRecentM", recentS: "catRecentS", pending: "catPendingDelta", episodes: "catEpisodes",
  assetRaw: "catAssetRaw", // the downloaded catalog.json held across import ticks (storageLarge)
  genres: "catGenres", // HDFull's own genre map { name: "m:id,s:id,..." } (storageLarge), fetched from genres.json
  genresAt: "catGenresAt", // when genres were last fetched
  importTotal: "catImportTotal", // total items of the import in flight (for the progress bar)
};
const sGet = (k) => { try { return kino.storage.get(k); } catch { return null; } };
const sSet = (k, v) => { try { kino.storage.set(k, v); } catch { /* storage full */ } };
const sDel = (k) => { try { kino.storage.remove(k); } catch { /* ignore */ } };
const UPSERT_BATCH = 500;

/**
 * Import `catalog` into kino.catalog, one batch of `batch` items per call, advancing a persisted
 * cursor; when the last batch lands it writes the recent id lists and the version/at markers and
 * clears the cursor. Resumable: a new call continues from the cursor. Returns { done, cursor, total }.
 */
export async function importCatalog(catalog, opts = {}) {
  const batch = Math.max(1, Math.min(UPSERT_BATCH, opts.batch || UPSERT_BATCH));
  const { items, recentMovies, recentSeries } = catalogItems(catalog.movies, catalog.series);
  let cursor = Number(sGet(CK.cursor)) || 0;
  if (sGet(CK.impVer) !== catalog.version) { cursor = 0; sSet(CK.impVer, catalog.version); } // a new version restarts
  if (cursor > items.length) cursor = 0;
  const end = Math.min(cursor + batch, items.length);
  if (cursor < end) {
    await kino.catalog.upsert(items.slice(cursor, end));
    cursor = end;
    sSet(CK.cursor, String(cursor));
  }
  if (cursor >= items.length) {
    sSet(CK.recentM, JSON.stringify(recentMovies));
    sSet(CK.recentS, JSON.stringify(recentSeries));
    sSet(CK.episodes, String(items.filter((it) => it.id[0] === "e").length));
    sSet(CK.ver, catalog.version);
    sSet(CK.at, String(Date.now()));
    sDel(CK.cursor);
    sDel(CK.impVer);
    return { done: true, cursor: items.length, total: items.length };
  }
  return { done: false, cursor, total: items.length };
}

// ---- catalog reads ----

/** kino.catalog.get for any number of ids, in batches of 500. */
async function getByIds(ids) {
  const out = [];
  for (let i = 0; i < ids.length; i += 500) out.push(...(await kino.catalog.get(ids.slice(i, i + 500))));
  return out;
}

/** The subset of `ids` present in the catalog (membership). */
export async function catHas(ids) {
  return new Set((await getByIds(ids)).map((it) => it.id));
}

/** The codes string behind a movie (`m:…`) or episode (`e:…`) ref, or null. */
export async function catCodesFor(ref) {
  const [it] = await kino.catalog.get([String(ref)]);
  return it && it.data && typeof it.data.c === "string" ? it.data.c : null;
}

/** The episode keys ("S.E") of a show, from its header item (reading key pages for a giant show). */
async function keysFromHeader(tv, h) {
  if (!h || !h.data) return [];
  let keyStr = h.data.e;
  if (keyStr == null && h.data.n) {
    const pageIds = [];
    for (let i = 0; i < h.data.n; i++) pageIds.push(`s:${tv}:k${i}`);
    const byId = new Map((await getByIds(pageIds)).map((p) => [p.id, p]));
    keyStr = pageIds.map((id) => (byId.get(id) && byId.get(id).data.e) || "").filter(Boolean).join(",");
  }
  return keyStr ? String(keyStr).split(",") : [];
}

/** A show's episodes in the catalog: `[{ s, e, codes }]`, sorted; [] if the show is not stored. */
export async function episodesOf(tv) {
  const [h] = await kino.catalog.get(["s:" + tv]);
  const keys = await keysFromHeader(tv, h);
  const epIds = keys.map((k) => { const d = k.indexOf("."); return `e:${tv}:${k.slice(0, d)}:${k.slice(d + 1)}`; });
  const codeById = new Map((await getByIds(epIds)).map((it) => [it.id, it.data && it.data.c]));
  const out = [];
  for (const k of keys) {
    const d = k.indexOf(".");
    const s = Number(k.slice(0, d)), e = Number(k.slice(d + 1));
    const codes = codeById.get(`e:${tv}:${s}:${e}`);
    if (codes) out.push({ s, e, codes });
  }
  out.sort((a, b) => a.s - b.s || a.e - b.e);
  return out;
}

/** The stored "recently added" id list for "movies" or "series" (newest first). */
export function catRecentIds(kind) {
  const raw = sGet(kind === "series" ? CK.recentS : CK.recentM);
  try { return raw ? JSON.parse(raw) : []; } catch { return []; }
}

// ---- asset download (the published catalog on the release) ----

// The release of the public plugin repo hosts the assets; the URL redirects to a GitHub CDN host,
// which kino.fetch follows (the manifest declares fetchHosts: "any"). Never a login: it is public.
const ASSET_BASE = "https://github.com/xuper-plugin/kino-plugin-hdfull/releases/download/catalog";

async function fetchJson(url) {
  try {
    const r = await kino.fetch(url, { timeoutMs: 15000 });
    if (!r || !r.ok) return null;
    return JSON.parse(await r.text());
  } catch { return null; }
}

/** The latest catalog version from the tiny witness file, or null (offline / not published). */
export async function fetchVersion() {
  const j = await fetchJson(ASSET_BASE + "/catalog.version.json");
  return j && typeof j.version === "string" ? j.version : null;
}

/** The full catalog.json, or null. */
export async function fetchCatalog() {
  return fetchJson(ASSET_BASE + "/catalog.json");
}

/** The delta from `fromVersion` to the latest, or null when there is none (404) -> caller falls back to full. */
export async function fetchDelta(fromVersion) {
  if (!fromVersion) return null;
  return fetchJson(ASSET_BASE + "/delta/" + encodeURIComponent(fromVersion) + ".json");
}

// ---- delta apply + background refresh job ----

/** Title ids of a compact block, in line order: "m:"/"s:" + the id before the first ":" of each line. */
function lineIds(text, prefix) {
  const ids = [];
  for (const line of String(text || "").split("\n")) {
    const i = line.indexOf(":");
    if (i > 0) ids.push(prefix + line.slice(0, i));
  }
  return ids;
}

/** Merge a delta's title ids into a recent list: brand-new titles go in front (the delta ships them
 * newest-first), changed titles keep their place, removed titles drop out. */
function mergeRecent(oldList, addIds, removeSet) {
  const have = new Set(oldList);
  const trulyNew = addIds.filter((id) => !have.has(id));
  return [...trulyNew, ...oldList.filter((id) => !removeSet.has(id))];
}

function parseList(raw) {
  try { return JSON.parse(raw || "[]"); } catch { return []; }
}

/** Every catalog item id of a title: a movie is itself; a series is its header + key pages + episodes. */
async function idsOfTitle(id) {
  if (id[0] === "m") return [id];
  const tv = id.slice(2);
  const [h] = await kino.catalog.get([id]);
  const ids = [id];
  if (h && h.data && h.data.n) for (let i = 0; i < h.data.n; i++) ids.push(`s:${tv}:k${i}`);
  for (const k of await keysFromHeader(tv, h)) { const d = k.indexOf("."); ids.push(`e:${tv}:${k.slice(0, d)}:${k.slice(d + 1)}`); }
  return ids;
}

/** Apply a delta to kino.catalog: remove gone titles (with their sub-items), upsert new/changed, update markers. */
export async function applyDelta(delta) {
  const removeIds = [];
  for (const id of delta.remove || []) removeIds.push(...(await idsOfTitle(id)));
  for (let i = 0; i < removeIds.length; i += 500) await kino.catalog.remove(removeIds.slice(i, i + 500));
  const { items } = catalogItems(delta.addMovies || "", delta.addSeries || "");
  for (let i = 0; i < items.length; i += UPSERT_BATCH) await kino.catalog.upsert(items.slice(i, i + UPSERT_BATCH));
  const removeSet = new Set(delta.remove || []);
  sSet(CK.recentM, JSON.stringify(mergeRecent(parseList(sGet(CK.recentM)), lineIds(delta.addMovies, "m:"), removeSet)));
  sSet(CK.recentS, JSON.stringify(mergeRecent(parseList(sGet(CK.recentS)), lineIds(delta.addSeries, "s:"), removeSet)));
  if (delta.version) sSet(CK.ver, delta.version);
  sSet(CK.at, String(Date.now()));
}

const JOB_STORE_CAP = 250000; // a job may write at most ~256 KB to kino.storage per run

/**
 * Background job (capability "schedule"): pre-download the pending update to kino.storage so the screen can
 * apply it on open. kino.catalog is NOT allowed in a job, so this never imports; the screen does that.
 */
export async function job() {
  const latest = await fetchVersion();
  if (!latest) return;                 // offline / not published
  const current = sGet(CK.ver);
  if (latest === current) return;      // up to date -> nothing pending
  if (current) {
    const delta = await fetchDelta(current);
    if (delta && delta.version === latest) {
      const json = JSON.stringify({ kind: "delta", data: delta });
      if (json.length <= JOB_STORE_CAP) { sSet(CK.pending, json); return; }
    }
  }
  sSet(CK.pending, JSON.stringify({ kind: "full", version: latest }));
}

// ---- refresh on open + recovery ----

const REFRESH_MS = 6 * 3600 * 1000;

/** Re-import needed: a version was recorded but the catalog is empty (restore on a new device / reset). */
export async function needsReimport() {
  return !!sGet(CK.ver) && (await kino.catalog.count()) === 0;
}

/** Begin a full (re)import: clear the DB and stash the asset, so the gate imports it tick by tick
 * (resumable, within each event's time budget) instead of blocking one event with the whole load. */
async function startFullImport(catalog) {
  await kino.catalog.clear();
  sDel(CK.cursor);
  sDel(CK.impVer);
  sSet(CK.assetRaw, JSON.stringify(catalog));
  sSet(CK.importTotal, String(catalogItems(catalog.movies, catalog.series).items.length));
}

/** Apply the update the job pre-downloaded (a delta, or a "full" marker). Returns true if it did work. */
export async function applyPending() {
  const raw = sGet(CK.pending);
  if (!raw) return false;
  sDel(CK.pending);
  let payload;
  try { payload = JSON.parse(raw); } catch { return false; }
  if (payload.kind === "delta" && payload.data) { await applyDelta(payload.data); return true; }
  if (payload.kind === "full") { const c = await fetchCatalog(); if (c) { await startFullImport(c); return true; } }
  return false;
}

/** On open: if the local copy is older than 6 h, refresh to the latest (a delta, else the full catalog). */
export async function ensureFresh() {
  const at = Number(sGet(CK.at)) || 0;
  if (at && Date.now() - at < REFRESH_MS) return;
  const latest = await fetchVersion();
  if (!latest) return;
  const current = sGet(CK.ver);
  if (latest === current) { sSet(CK.at, String(Date.now())); return; } // already latest; reset the clock
  if (current) {
    const delta = await fetchDelta(current);
    if (delta && delta.version === latest) { await applyDelta(delta); return; } // a stale delta that misses latest -> full
  }
  const c = await fetchCatalog();
  if (c) await startFullImport(c);
}

// ---- 2. dead-copy tracking ----

// Membership, codes and episodes now come from kino.catalog (see "catalog reads" above). Here only the
// per-device record of copies that failed to play, so a dead copy is not tried again.

// A copy that failed to play is remembered 30 days (the host deleted the file: HDFull still links it), so it is not
// tried again, and a title or episode whose copies all failed leaves the lists. Only real play attempts feed it.
const DEAD_MS = 30 * 24 * 3600 * 1000;
/** @type {Set<string> | null} */
let deadSet = null;
function dead() {
  if (deadSet) return deadSet;
  try { deadSet = new Set(JSON.parse(kino.storage.get("dead") || "[]")); } catch { deadSet = new Set(); }
  return deadSet;
}
function markDead(slot) {
  const d = dead();
  if (d.has(slot)) return;
  d.add(slot);
  // ~16 bytes a slot: a few thousand fit in kino.storage next to the TMDB copies.
  try { kino.storage.set("dead", JSON.stringify([...d].slice(-6000)), { ttlMs: DEAD_MS }); } catch { /* full: forget */ }
}
const liveCodes = (codes) => (codes || []).filter((c) => !dead().has(c));

// vidmoly says "not found" both for a deleted file and to an IP that asked too much: one such answer only makes the
// copy suspect; a second one at least an hour later makes it dead. A copy that plays again stops being suspect.
const SUSPECT_GAP_MS = 3600 * 1000;
function suspects() {
  try { return JSON.parse(kino.storage.get("suspect") || "{}"); } catch { return {}; }
}
function saveSuspects(all) {
  try { kino.storage.set("suspect", JSON.stringify(all), { ttlMs: DEAD_MS }); } catch { /* full: forget */ }
}
/** One failed play of [slot]: dead now, dead on a second suspect failure, or nothing (network trouble). */
function noteFailure(slot, e) {
  if (gone(e)) { markDead(slot); return; }
  if (!suspect(e)) return;
  const all = suspects();
  const first = all[slot];
  if (first && Date.now() - first >= SUSPECT_GAP_MS) {
    delete all[slot];
    saveSuspects(all);
    markDead(slot);
  } else if (!first) {
    all[slot] = Date.now();
    saveSuspects(all);
  }
}
function notePlayed(slot) {
  const all = suspects();
  if (all[slot]) { delete all[slot]; saveSuspects(all); }
}

// ---- 3. TMDB (live, through Kino) ----

const IMG = "https://image.tmdb.org/t/p/";
const img = (size, p) => (p ? IMG + size + p : undefined);
const lang = () => (isEs() ? "es-MX" : "en-US");
const year = (d) => (typeof d === "string" && /^\d{4}/.test(d) ? Number(d.slice(0, 4)) : undefined);

async function tmdb(path, params = {}) {
  try {
    return await kino.tmdb(path, { language: lang(), ...params });
  } catch (e) {
    if (e && e.code === "not_found") throw kino.error("not_found", "tmdb 404 " + path, { userMessage: t("notFound") });
    if (e && e.userMessage) throw e;
    throw kino.error("unavailable", "tmdb " + path + " " + (e && e.code), { userMessage: t("tmdbDown") });
  }
}

// kino.tmdb answers 20 calls per 10 s per plugin on Kino's key (40 with the person's own): a slim copy of each
// title (14 days) and of each filtered list page (6 h) lives in kino.storage (256 KB), so a reopened Home costs nothing.
const DAY = 24 * 3600 * 1000;
function cacheGet(key) {
  try { const v = kino.storage.get(key); return v ? JSON.parse(v) : null; } catch { return null; }
}
function cacheSet(key, value, ttlMs) {
  try { kino.storage.set(key, JSON.stringify(value), { ttlMs }); } catch { /* storage full: no copy */ }
}
/** Only what a card needs; `tv` marks a series. */
const slim = (m, tv) => ({ id: m.id, tv: tv ? 1 : 0, title: (tv ? m.name || m.original_name : m.title || m.original_title) || "",
  poster_path: m.poster_path, backdrop_path: m.backdrop_path, date: tv ? m.first_air_date : m.release_date,
  vote_average: m.vote_average });

/** A card from a slim title (movie or series). */
function card(m, ref) {
  const tv = !!m.tv;
  return {
    id: (tv ? "s" : "m") + m.id,
    ref: ref || (tv ? "s:" : "m:") + m.id,
    title: m.title,
    kind: /** @type {"movie" | "series"} */ (tv ? "series" : "movie"),
    year: year(m.date),
    poster: img("w342", m.poster_path),
    backdrop: img("w780", m.backdrop_path),
    rating: m.vote_average ? Math.round(m.vote_average * 10) / 10 : undefined,
    ids: { tmdb: m.id },
  };
}

/** A slim TMDB movie for one index id ("123" or "i<imdb>"), or null. */
async function movieFor(id) {
  const key = `mv:${lang()}:${id}`;
  const hit = cacheGet(key);
  if (hit) return hit;
  let m = null;
  try {
    if (id[0] !== "i") m = await tmdb("/movie/" + id);
    else m = ((await tmdb("/find/tt" + id.slice(1), { external_source: "imdb_id" })).movie_results || [])[0] || null;
  } catch { return null; }
  if (!m) return null;
  const s = slim(m, false);
  cacheSet(key, s, 14 * DAY);
  return s;
}

/** A slim TMDB series, or null. */
async function showFor(id) {
  const key = `tv:${lang()}:${id}`;
  const hit = cacheGet(key);
  if (hit) return hit;
  let m = null;
  try { m = await tmdb("/tv/" + id); } catch { return null; }
  const s = slim(m, true);
  cacheSet(key, s, 14 * DAY);
  return s;
}

/** One TMDB list page reduced to the titles in the index (cached 6 h). */
async function listPage(path, params, page, tv) {
  const key = `pg:${lang()}:${path}:${JSON.stringify(params)}:${page}`;
  const hit = cacheGet(key);
  if (hit) return hit;
  const data = await tmdb(path, { ...params, page });
  const results = (data.results || []).filter((m) => m.poster_path);
  const present = await catHas(results.map((m) => (tv ? "s:" : "m:") + m.id));
  const out = { total: Math.min(data.total_pages || 1, 500),
    hits: results.filter((m) => present.has((tv ? "s:" : "m:") + m.id)).map((m) => slim(m, tv)) };
  cacheSet(key, out, DAY / 4);
  return out;
}

// ---- 4. rows / browse / search / details / episodes ----

const LISTS = {
  trending: { path: "/trending/movie/week", key: "trending" },
  trendingTv: { path: "/trending/tv/week", key: "trendingTv", tv: true },
  popular: { path: "/movie/popular", key: "popular" },
  popularTv: { path: "/tv/popular", key: "popularTv", tv: true },
  now: { path: "/movie/now_playing", key: "nowPlaying" },
  top: { path: "/movie/top_rated", key: "topRated" },
  topTv: { path: "/tv/top_rated", key: "topRatedTv", tv: true },
};
const PAGE = 20;
const MAX_TMDB_PAGES = 6;
// TMDB calls a cold Home may make: 7 + 7 recent titles + 4 list pages = 18, under Kino's 20 per 10 s.
const HOME_RECENT = 7;
const HOME_LISTS = ["trending", "trendingTv", "popular", "popularTv"];

/** Walks TMDB pages from [startPage], keeping only titles in the index, until [PAGE] items or the cap. */
async function filtered(path, params, startPage, tv, maxPages = MAX_TMDB_PAGES) {
  const items = [];
  let page = startPage;
  let total = 1;
  for (let n = 0; n < maxPages && items.length < PAGE; n++, page++) {
    const data = await listPage(path, params, page, tv);
    total = data.total;
    for (const m of data.hits) items.push(card(m));
    if (page >= total) return { items, next: undefined };
  }
  return { items, next: String(page) };
}

/** Prefixed catalog ids ("m:<id>"/"s:<id>") -> KinoItems, posters/titles from TMDB (cached by Kino). */
async function idsToItems(ids, tv) {
  const found = await Promise.all(ids.map((id) => (tv ? showFor : movieFor)(id.slice(2))));
  const items = [];
  found.forEach((m, i) => { if (m && m.poster_path) items.push(card(m, ids[i])); });
  return items;
}

/** The index's own order (newest first), one page, details from TMDB live. */
async function recent(cursor, size, tv) {
  const ids = catRecentIds(tv ? "series" : "movies"); // "m:<id>" / "s:<id>", newest first
  const from = Math.max(0, parseInt(cursor || "0", 10) || 0);
  const slice = ids.slice(from, from + size);
  const items = await idsToItems(slice, tv);
  return { items, next: from + size < ids.length ? String(from + size) : undefined };
}

/** Download HDFull's genre map (genres.json) and cache it; refetch at most once a day. */
async function ensureGenres() {
  const at = Number(sGet(CK.genresAt)) || 0;
  if (sGet(CK.genres) && Date.now() - at < 86400000) return;
  const g = await fetchJson(ASSET_BASE + "/genres.json");
  if (g && g.genres) { sSet(CK.genres, JSON.stringify(g.genres)); sSet(CK.genresAt, String(Date.now())); }
}

/** The stored HDFull genre map, filtered to the tab's ids that are still in the catalog, biggest first. */
function genreRailsFor(tv) {
  let map;
  try { map = JSON.parse(sGet(CK.genres) || "{}"); } catch { return []; }
  const prefix = tv ? "s:" : "m:";
  return Object.keys(map)
    .map((name) => ({ name, ids: String(map[name]).split(",").filter((id) => id.startsWith(prefix)) }))
    .filter((g) => g.ids.length >= 6)
    .sort((a, b) => b.ids.length - a.ids.length);
}

export async function home() {
  // Fresh install (catalog not downloaded yet): contribute no rows instead of throwing. Throwing makes
  // Kino show "El Inicio no cargó" on the home; the user downloads the catalog from the plugin's screen.
  if (!catRecentIds("movies").length && !catRecentIds("series").length) return [];
  const defs = [
    ["recent", () => recent(null, HOME_RECENT, false)],
    ["recentTv", () => recent(null, HOME_RECENT, true)],
    ...HOME_LISTS.map((id) => [id, () => filtered(LISTS[id].path, {}, 1, !!LISTS[id].tv, 1)]),
  ];
  const settled = await Promise.allSettled(defs.map(([, fn]) => fn()));
  const rows = [];
  settled.forEach((r, i) => {
    if (r.status !== "fulfilled" || !r.value.items.length) return;
    const id = defs[i][0];
    const tv = id === "recentTv" || !!(LISTS[id] && LISTS[id].tv);
    const title = id === "recent" || id === "recentTv" ? t(id) : t(LISTS[id].key);
    rows.push({ id, title, ref: "browse:" + id, items: r.value.items,
      genre: /** @type {"peliculas" | "series"} */ (tv ? "series" : "peliculas") });
  });
  // A transient all-TMDB-failure leaves no rows: contribute nothing rather than throwing (which Kino
  // surfaces as "El Inicio no cargó"); the next home refresh fills it.
  return rows;
}

export async function section() {
  const rows = await home();
  const first = rows[0] && rows[0].items.find((i) => i.backdrop);
  return { rows, ...(first ? { hero: { title: first.title, image: first.backdrop } } : {}) };
}

export async function browse(ref, cursor) {
  const parts = String(ref).split(":");
  if (parts[1] === "recent") return recent(cursor, PAGE, false);
  if (parts[1] === "recentTv") return recent(cursor, PAGE, true);
  const page = Math.max(1, parseInt(cursor || "1", 10) || 1);
  if (parts[1] === "hdgenre") { // "see all" of an HDFull genre row: its catalog titles, paged
    let map; try { map = JSON.parse(sGet(CK.genres) || "{}"); } catch { map = {}; }
    const ids = String(map[decodeURIComponent(parts.slice(2).join(":"))] || "").split(",").filter(Boolean);
    const from = (page - 1) * PAGE;
    const slice = ids.slice(from, from + PAGE);
    const items = [...await idsToItems(slice.filter((id) => id[0] === "m"), false), ...await idsToItems(slice.filter((id) => id[0] === "s"), true)];
    return { items, next: from + PAGE < ids.length ? String(page + 1) : undefined };
  }
  if (parts[1] === "genre" && /^\d+$/.test(parts[2] || "")) {
    return filtered("/discover/movie", { with_genres: parts[2], sort_by: "popularity.desc", "vote_count.gte": 20 }, page, false);
  }
  const def = LISTS[parts[1]];
  if (!def) throw kino.error("not_found", "unknown browse ref: " + ref, { userMessage: t("notFound") });
  return filtered(def.path, {}, page, !!def.tv);
}

export async function categories() {
  const data = await tmdb("/genre/movie/list");
  return (data.genres || []).slice(0, 19).map((g) => ({
    id: "g" + g.id, title: `${t("genre")} ${g.name}`.slice(0, 40), ref: "browse:genre:" + g.id,
  }));
}

export async function search(query) {
  const q = (typeof query === "string" ? query : (query && query.q) || "").trim();
  if (!q) return [];
  const y = query && typeof query === "object" && query.year ? query.year : undefined;
  const asks = [
    ...[1, 2, 3].map((page) => [false, tmdb("/search/movie", { query: q, include_adult: false, page, ...(y ? { year: y } : {}) })]),
    ...[1, 2].map((page) => [true, tmdb("/search/tv", { query: q, include_adult: false, page, ...(y ? { first_air_date_year: y } : {}) })]),
  ];
  const pages = await Promise.allSettled(asks.map(([, p]) => p));
  if (pages[0].status === "rejected" && pages[3].status === "rejected") throw pages[0].reason;
  const cand = [];
  pages.forEach((r, i) => {
    if (r.status !== "fulfilled") return;
    const tv = asks[i][0];
    for (const m of r.value.results || []) {
      if (m.poster_path) cand.push({ m, tv, id: (tv ? "s:" : "m:") + m.id });
    }
  });
  const present = await catHas(cand.map((c) => c.id));
  const items = [];
  const seen = new Set();
  for (const c of cand) {
    if (!present.has(c.id) || seen.has(c.id)) continue;
    seen.add(c.id);
    items.push(card(slim(c.m, c.tv)));
  }
  return items;
}

const parseMovieRef = (ref) => {
  const m = /^m:(i?\d+)$/.exec(String(ref || ""));
  return m ? m[1] : null;
};
const parseShowRef = (ref) => {
  const m = /^s:(\d+)$/.exec(String(ref || ""));
  return m ? m[1] : null;
};

export async function details(ref) {
  const sid = parseShowRef(ref);
  if (sid) {
    const d = await tmdb("/tv/" + sid, { append_to_response: "external_ids" });
    const imdb = d.external_ids && d.external_ids.imdb_id;
    return {
      title: d.name,
      poster: img("w500", d.poster_path),
      backdrop: img("w1280", d.backdrop_path),
      overview: d.overview || undefined,
      genres: (d.genres || []).map((g) => g.name).slice(0, 5),
      year: year(d.first_air_date),
      rating: d.vote_average ? Math.round(d.vote_average * 10) / 10 : undefined,
      ids: { tmdb: d.id, ...(/^tt\d{5,10}$/.test(imdb || "") ? { imdb } : {}) },
    };
  }
  const id = parseMovieRef(ref);
  if (!id) return null;
  const m = await movieFor(id);
  if (!m) throw kino.error("not_found", "no tmdb for " + id, { userMessage: t("notFound") });
  const d = await tmdb("/movie/" + m.id);
  return {
    title: d.title,
    poster: img("w500", d.poster_path),
    backdrop: img("w1280", d.backdrop_path),
    overview: d.overview || undefined,
    genres: (d.genres || []).map((g) => g.name).slice(0, 5),
    year: year(d.release_date),
    rating: d.vote_average ? Math.round(d.vote_average * 10) / 10 : undefined,
    runtimeMinutes: d.runtime > 0 ? d.runtime : undefined,
    ids: { tmdb: d.id, ...(/^tt\d{5,10}$/.test(d.imdb_id || "") ? { imdb: d.imdb_id } : {}) },
  };
}

/** Only the episodes in the index (those with a captcha-free copy), named and pictured by TMDB when it can. */
export async function episodes(ref) {
  const id = parseShowRef(ref);
  if (!id) throw kino.error("not_found", "not a series ref", { userMessage: t("notFound") });
  const have = await episodesOf(id); // [{ s, e, codes }]
  if (!have.length) throw kino.error("not_found", "series not in index: " + id, { userMessage: t("notFound") });
  const seasons = [...new Set(have.map((x) => x.s))].sort((a, b) => a - b);

  /** @type {any} */
  let show = null;
  /** @type {Map<string, any>} */
  const info = new Map();
  try {
    // append_to_response takes up to 20 sub-requests per call: the first call carries the first 19 seasons.
    show = await tmdb("/tv/" + id, { append_to_response: ["external_ids", ...seasons.slice(0, 19).map((s) => "season/" + s)].join(",") });
    const more = [];
    for (let i = 19; i < seasons.length; i += 20) more.push(seasons.slice(i, i + 20));
    const extra = await Promise.allSettled(more.map((g) => tmdb("/tv/" + id, { append_to_response: g.map((s) => "season/" + s).join(",") })));
    const blocks = [show, ...extra.filter((r) => r.status === "fulfilled").map((r) => /** @type {any} */ (r).value)];
    for (const b of blocks) {
      for (const s of seasons) {
        const sd = b["season/" + s];
        for (const ep of (sd && sd.episodes) || []) info.set(`${s}.${ep.episode_number}`, ep);
      }
    }
  } catch { /* no TMDB: the episodes still play, numbered only */ }

  const out = [];
  for (const { s, e, codes } of have) {
    if (!liveCodes(codes.split(",")).length) continue;
    const ep = info.get(`${s}.${e}`);
    out.push({
      season: s,
      number: e,
      ref: `e:${id}:${s}:${e}`,
      title: (ep && ep.name) || `${t("episode")} ${e}`,
      still: ep ? img("w300", ep.still_path) : undefined,
      overview: (ep && ep.overview) || undefined,
      airDate: ep && /^\d{4}-\d{2}-\d{2}$/.test(ep.air_date || "") ? ep.air_date : undefined,
      runtimeMinutes: ep && ep.runtime > 0 && ep.runtime <= 1000 ? ep.runtime : undefined,
    });
  }
  out.sort((x, y) => x.season - y.season || x.number - y.number);
  if (!show) return { episodes: out };
  const imdb = show.external_ids && show.external_ids.imdb_id;
  return {
    series: {
      title: show.name,
      poster: img("w500", show.poster_path),
      backdrop: img("w1280", show.backdrop_path),
      overview: show.overview || undefined,
      genres: (show.genres || []).map((g) => g.name).slice(0, 5),
      year: year(show.first_air_date),
      rating: show.vote_average ? Math.round(show.vote_average * 10) / 10 : undefined,
      ids: { tmdb: show.id, ...(/^tt\d{5,10}$/.test(imdb || "") ? { imdb } : {}) },
    },
    episodes: out,
  };
}

// ---- 5. resolvers (captcha-free hosts only) ----

const UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36";

/** The host says the file is not there: this copy is remembered as dead. */
function goneErr(message) {
  // The flag rides in the message too, in case the runtime hands back a sealed error object.
  const e = kino.error("unavailable", "gone " + message);
  try { /** @type {any} */ (e).gone = true; } catch { /* sealed */ }
  return e;
}

/** When the resolver isn't installed, every door call fails provider_missing. HDFull has no own extractor to
 *  fall back on, so tell the person to install it (the one thing they can do, from anywhere they tried to
 *  play), and tag the error so resolve() stops trying the other copies at once. */
function resolverMissingError() {
  const e = kino.error("unavailable", "kino-resolver not installed", { userMessage: t("needResolver") });
  try { e.resolverMissing = true; } catch { /* sealed */ }
  return e;
}

// Every hoster embed is resolved by the shared kino-resolver (its provider door), not by HDFull itself.
// HDFull only builds the embed url (per hoster, below) and translates the door's stream into its own shape.
// The hosters it indexes are captcha-free (inline), so the door resolves them without the hidden browser.
async function viaResolver(embedUrl) {
  let res;
  try { res = await kino.plugins.call("resolver", "resolve", { url: embedUrl, referer: "https://hdfull.org/" }); }
  catch (e) {
    if (e && e.code === "provider_missing") throw resolverMissingError();
    throw kino.error("unavailable", "resolver " + ((e && e.code) || "call failed") + ": " + embedUrl);
  }
  const s = (res && Array.isArray(res.streams) ? res.streams : []).find((x) => x && x.url);
  if (!s) {
    if (res && res.error === "dead") throw goneErr("dead " + embedUrl);
    throw kino.error("unavailable", "no stream: " + embedUrl);
  }
  const headers = { "User-Agent": UA };
  if (s.referer) headers.Referer = s.referer;
  if (Array.isArray(s.headers)) { for (const h of s.headers) if (h && h.name) headers[h.name] = String(h.value); }
  else if (s.headers && typeof s.headers === "object") Object.assign(headers, s.headers);
  return { url: s.url, mime: s.kind === "hls" ? "application/x-mpegURL" : "video/mp4", headers, expiresInSeconds: 3600 };
}

const vidmoly = (code) => viaResolver(`https://vidmoly.biz/embed-${code}.html`);
const streamtape = (code) => viaResolver(`https://streamtape.com/e/${code}`);
const mixdrop = (code) => viaResolver(`https://mixdrop.bz/e/${code}`);
const vidoza = (code) => viaResolver(`https://vidoza.net/embed-${code}.html`);
const gamovideo = (code) => viaResolver(`https://gamovideo.com/${code}`);

/** True when the host answered that the file is not there (not a network or rate-limit failure). */
const gone = (e) => !!(e && (e.gone || /^gone /.test(String(e.message || ""))));
/** True when vidmoly showed no playlist: deleted or blocked, it cannot tell which. */
const suspect = (e) => /^suspect /.test(String((e && e.message) || ""));
function play(slot) {
  const host = slot[1];
  const code = slot.slice(2);
  if (!/^[A-Za-z0-9]{6,40}$/.test(code)) throw kino.error("invalid_request", "bad code " + slot);
  if (host === "v") return vidmoly(code);
  if (host === "s") return streamtape(code);
  if (host === "m") return mixdrop(code);
  if (host === "o") return vidoza(code);
  if (host === "g") return gamovideo(code);
  throw kino.error("invalid_request", "unknown host " + slot);
}

const HOST_NAMES = { v: "Vidmoly", s: "Streamtape", m: "Mixdrop", o: "Vidoza", g: "Gamovideo" };
const label = (slot) => `${T[isEs() ? "es" : "en"].lang[slot[0]] || slot[0]} · ${HOST_NAMES[slot[1]] || slot[1]}`;

// ---- 6. resolve ----

/** Codes of one title, the preferred language first, vidmoly (HLS) before streamtape and mixdrop within a language. */
function ranked(codes) {
  const pref = String(cfg("audio", "E"));
  const score = (c) => (c[0] === pref ? 0 : 10) + "ELSO".indexOf(c[0]) + ({ v: 0, s: 0.3, m: 0.6, o: 0.7, g: 0.9 }[c[1]] || 1);
  return [...codes].sort((a, b) => score(a) - score(b));
}

export async function resolve(ref) {
  const s = String(ref || "");
  const lazy = /^c:([ELSO][vsmog][A-Za-z0-9]{6,40})$/.exec(s);
  if (lazy) {
    try { const st = await play(lazy[1]); notePlayed(lazy[1]); return st; } catch (e) {
      if (e && e.resolverMissing) throw e;
      noteFailure(lazy[1], e);
      throw kino.error("unavailable", "copy failed", { userMessage: t("noStreams") });
    }
  }
  const codesStr = await catCodesFor(s);
  const codes = codesStr ? codesStr.split(",") : [];
  if (!codes.length) throw kino.error("not_found", "not in index: " + s, { userMessage: t("notFound") });
  const list = ranked(liveCodes(codes));
  for (let i = 0; i < Math.min(list.length, 4); i++) {
    let stream;
    try { stream = await play(list[i]); notePlayed(list[i]); } catch (e) { if (e && e.resolverMissing) throw e; noteFailure(list[i], e); continue; }
    const rest = list.filter((_, j) => j !== i);
    return { ...stream, alternatives: rest.map((c) => ({ label: label(c), ref: "c:" + c })) };
  }
  throw kino.error("unavailable", "no copy loaded for " + s, { userMessage: t("noStreams") });
}

// ---- screen (capability "screen"): gate + rich view ----

const SUPPORT_URL = "https://ko-fi.com/xuperplugins";
const RESOLVER_REPO = "xuper-plugin/kino-plugin-kino-resolver";

/** The donation affordance: a QR on TV (a TV can't open a link well), a heart button on phone/desktop. */
function supportNode(device) {
  if (device === "tv") {
    return { type: "QrImage", value: SUPPORT_URL, size: "large",
      labelText: "Si te gusta mi trabajo, escanéalo y apóyame", labelTextEn: "If you like my work, scan it and support me" };
  }
  return { type: "ElevatedButton", icon: "heart", labelText: "Si te gusta mi trabajo, apóyame",
    labelTextEn: "If you like my work, support me", onPressed: "support" };
}

/** The resolver install gate: shown as the first screen while kino-resolver (HDFull delegates every hoster
 *  to it) is not installed. Once it is, screen() goes on to the catalog gate / rich view. The donate
 *  affordance sits under the install button, as on every gate. */
function resolverGateView(device) {
  return {
    type: "Scaffold",
    appBar: { type: "AppBar", title: "HDFull" },
    body: { type: "Column", mainAxisAlignment: "center", crossAxisAlignment: "center", padding: 24, children: [
      { type: "Text", text: "Necesitas el motor de reproducción", textEn: "You need the playback engine", style: "h3" },
      { type: "Text", style: "p",
        text: "HDFull reproduce a través de Kino Resolver (gratis). Instálalo una vez y sirve para este y para otros plugins de sitios.",
        textEn: "HDFull plays through Kino Resolver (free). Install it once and it works here and in other site plugins." },
      { type: "ElevatedButton", labelText: "Instalar Kino Resolver", labelTextEn: "Install Kino Resolver",
        onPressed: { go: { installPlugin: { repo: RESOLVER_REPO } } } },
      supportNode(device),
    ] },
  };
}

/** First-run gate. Three phases, each with its own progress bar:
 *  - idle: a Download button.
 *  - downloading: an indeterminate bar (a single fetch gives no byte progress) + a tick that fetches.
 *  - importing: a determinate bar (done/total) + a tick that imports one batch. */
function gateView(state, device) {
  const phase = state.phase || (state.importing ? "importing" : "idle");
  const children = [
    { type: "Text", text: "HDFull", style: "h1" },
    { type: "Text", text: "Películas y series que se ven sin captcha.",
      textEn: "Movies and series that play without a captcha.", style: "p" },
  ];
  let tick = null;
  if (phase === "loading") {
    children.push({ type: "CircularProgressIndicator", text: "Cargando…", textEn: "Loading…" });
  } else if (phase === "downloading") {
    children.push({ type: "LinearProgressIndicator",
      labelText: "Descargando catálogo…", labelTextEn: "Downloading catalog…" });
    tick = "fetchCatalog";
  } else if (phase === "importing") {
    const done = Number(state.cursor) || 0;
    const total = Number(state.total) || 0;
    children.push({ type: "LinearProgressIndicator", value: total ? Math.min(1, done / total) : 0,
      labelText: `Importando catálogo… ${done} / ${total}`, labelTextEn: `Importing catalog… ${done} / ${total}` });
    tick = "importTick";
  } else {
    children.push({ type: "ElevatedButton", labelText: "Descargar catálogo", labelTextEn: "Download catalog", onPressed: "download" });
    children.push(supportNode(device));
  }
  const tree = {
    type: "Scaffold",
    appBar: { type: "AppBar", title: "HDFull" },
    body: { type: "Column", mainAxisAlignment: "center", crossAxisAlignment: "center", padding: 24, children },
  };
  return tick ? { ...tree, every: [{ ms: 1000, event: tick }] } : tree;
}

/** A featured title as a hero slide; its button opens the title's page. */
function heroCard(c) {
  return {
    type: "heroCard",
    title: c.title,
    text: [c.year, c.rating ? "★ " + c.rating : null].filter(Boolean).join(" · "),
    image: c.backdrop,
    buttons: [{
      type: "ElevatedButton", labelText: "Ver", labelTextEn: "Watch",
      onPressed: { go: { title: { ref: c.ref, kind: c.kind, id: c.ids && String(c.ids.tmdb), title: c.title } } },
    }],
  };
}

/** Load a tab's data (catalog + TMDB). Runs in screenEvent (network is allowed there), NOT in screen().
 *  Returns a plain `view` object the pure renderer draws from. */
// Posters come from TMDB (cached by Kino for 7 days), limited to ~20 fresh calls / 10 s. The first open
// of a tab fetches this many; genre rails fill in as the cache warms on later opens.
const VIEW_RECENT = 9;
const VIEW_GENRES = 6;
const VIEW_GENRE_ITEMS = 10;

async function loadView(tab) {
  const tv = tab === "series";
  await ensureGenres();
  const rec = await recent(null, VIEW_RECENT, tv);
  const rails = [];
  if (rec.items.length) {
    rails.push({ title: tv ? "Series recién agregadas" : "Recién agregadas a HDFull",
      titleEn: tv ? "Recently added series" : "Recently added", ref: tv ? "browse:recentTv" : "browse:recent", items: rec.items.slice(0, 30) });
  }
  // A row per HDFull genre (from genres.json), biggest first. Kino opens a tapped title; "see all" browses the genre.
  for (const g of genreRailsFor(tv).slice(0, VIEW_GENRES)) {
    const items = await idsToItems(g.ids.slice(0, VIEW_GENRE_ITEMS), tv);
    if (items.length) rails.push({ title: g.name, titleEn: g.name, ref: "browse:hdgenre:" + encodeURIComponent(g.name), items });
  }
  return { tab, heroes: rec.items.filter((i) => i.backdrop).slice(0, 5), rails };
}

/** Pure render of a tab's body from a pre-loaded `view` (no network): hero carousel + category rails. */
function browseBodyView(view) {
  const children = [];
  const v = view || { heroes: [], rails: [] };
  if ((v.heroes || []).length) children.push({ type: "PageView", viewportFraction: 1, children: v.heroes.map(heroCard) });
  for (const rail of v.rails || []) {
    if (rail.items && rail.items.length) {
      children.push({ type: "titleRail", title: rail.title, titleEn: rail.titleEn, ref: rail.ref, items: rail.items });
    }
  }
  return { type: "SingleChildScrollView", flex: 1, children: [{ type: "Column", gap: 12, children }] };
}

/** The settings view inside the screen: the preferred language (set in Kino's form) and the donation affordance. */
function settingsBody(device) {
  return { type: "SingleChildScrollView", flex: 1, children: [{ type: "Column", padding: 16, gap: 12, children: [
    { type: "ListTile", title: "Idioma preferido", titleEn: "Preferred language",
      subtitle: "Cámbialo en los ajustes del plugin", subtitleEn: "Change it in the plugin settings" },
    { type: "Divider" },
    supportNode(device),
  ] }] };
}

/** Pure render of the rich view from `state` (its data was loaded by screenEvent into state.view). */
function richView(state, device) {
  const searching = !!state.searching;
  const tab = state.tab === "series" ? "series" : state.tab === "settings" ? "settings" : "movies";
  const appBar = searching
    ? { type: "AppBar", mergeWithKinoBar: true, dense: true,
        leading: { type: "IconButton", icon: "arrow_back", onPressed: "close_search", labelText: "Cerrar", labelTextEn: "Close" },
        title: { type: "TextField", key: "q", kind: "search", autofocus: true, hintText: "Buscar en HDFull", hintTextEn: "Search HDFull",
          onSubmitted: "search", trailingIcon: "search", trailingLabel: "Buscar", trailingLabelEn: "Search", onTrailingTap: "search" } }
    : { type: "AppBar", title: "HDFull", mergeWithKinoBar: true, dense: true,
        leading: { type: "IconButton", icon: "close", onPressed: "close_screen", labelText: "Cerrar", labelTextEn: "Close" },
        actions: [
          { type: "IconButton", icon: "search", onPressed: "open_search", labelText: "Buscar", labelTextEn: "Search" },
          { type: "IconButton", icon: "refresh", onPressed: "refresh", labelText: "Actualizar", labelTextEn: "Refresh" },
          { type: "IconButton", icon: "settings", onPressed: "open_settings", labelText: "Ajustes", labelTextEn: "Settings" },
        ] };
  const tabBar = { type: "TabBar", key: "tab", value: tab === "settings" ? "movies" : tab, onChanged: "tab",
    tabs: [{ value: "movies", label: "Películas", labelEn: "Movies" }, { value: "series", label: "Series", labelEn: "Series" }] };
  const body = tab === "settings" ? settingsBody(device) : browseBodyView(state.view);
  return { type: "Scaffold", appBar, body: { type: "Column", children: [tabBar, body] } };
}

// PURE VIEW: render ONLY from `state`. Kino forbids network/data access here; everything is loaded by
// screenEvent (the reserved `open` event and the others) and handed back in `state`.
export async function screen(arg) {
  const device = (arg && arg.device) || "phone";
  if (!(arg && arg.installed && arg.installed[RESOLVER_REPO])) return resolverGateView(device);
  const state = (arg && arg.state) || {};
  if (state.downloading) return gateView({ ...state, phase: "downloading" }, device);
  if (state.importing) return gateView({ ...state, phase: "importing" }, device);
  if (!state.ready) return gateView({ ...state, phase: "loading" }, device); // the `open` event hasn't loaded yet
  if (state.empty) return gateView({ ...state, phase: "idle" }, device);
  return richView(state, device);
}

/** The "loaded" state patch for a tab: its view data (catalog + TMDB). Runs in screenEvent only. */
async function readyState(tab) {
  const t = tab === "series" ? "series" : tab === "settings" ? "settings" : "movies";
  if (t === "settings") return { ready: true, empty: false, tab: "settings", view: { tab: "settings" } };
  return { ready: true, empty: false, tab: t, view: await loadView(t) };
}

export async function screenEvent(ev) {
  const name = ev && (ev.name != null ? ev.name : ev.event);
  const value = ev && (ev.value != null ? ev.value : ev.arg);
  const state = (ev && ev.state) || {};
  try {
    switch (name) {
      // The reserved first event: load everything here (network/catalog allowed), hand it back in state.
      case "open": {
        if (sGet(CK.assetRaw)) { // an import was in flight: resume it (the gate ticks importTick)
          return { state: { ready: true, importing: true, cursor: Number(sGet(CK.cursor)) || 0, total: Number(sGet(CK.importTotal)) || 0 } };
        }
        // Fresh install: auto-start the download so opening the plugin populates it (no manual tap).
        // If the fetch fails, fetchCatalog flips to the "Descargar catálogo" button to retry.
        if ((await kino.catalog.count()) === 0) return { state: { ready: true, downloading: true } };
        await applyPending();
        await ensureFresh();
        return { state: await readyState(state.tab || "movies") };
      }
      case "download":
        // Flip to the "downloading" phase first so its progress bar renders; the fetch runs on the
        // next tick (a single fetch can't report byte progress, so the bar is indeterminate).
        return { state: { downloading: true } };
      case "fetchCatalog": {
        const c = await fetchCatalog();
        if (!c) return { state: { downloading: false, ready: true, empty: true }, toast: { text: "No se pudo descargar; reintenta", textEn: "Download failed; try again", role: "error" } };
        sSet(CK.assetRaw, JSON.stringify(c));
        sDel(CK.cursor);
        sDel(CK.impVer);
        const total = catalogItems(c.movies, c.series).items.length;
        sSet(CK.importTotal, String(total));
        return { state: { downloading: false, importing: true, cursor: 0, total } };
      }
      case "importTick": {
        const raw = sGet(CK.assetRaw);
        if (!raw) return { state: { importing: false, ...(await readyState(state.tab || "movies")) } };
        const r = await importCatalog(JSON.parse(raw), { batch: UPSERT_BATCH });
        if (r.done) {
          sDel(CK.assetRaw); sDel(CK.importTotal);
          return { state: { importing: false, cursor: r.total, total: r.total, ...(await readyState(state.tab || "movies")) } };
        }
        return { state: { cursor: r.cursor, total: r.total } };
      }
      case "support":
        return { go: { url: { href: SUPPORT_URL } } };
      case "close_screen":
        return { close: true };
      case "tab": {
        const t = value === "series" ? "series" : value === "settings" ? "settings" : "movies";
        return { state: { searching: false, ...(await readyState(t)) } };
      }
      case "open_search":
        return { state: { searching: true } };
      case "open_settings":
        return { state: { tab: "settings", searching: false, ready: true, empty: false, view: { tab: "settings" } } };
      case "close_search":
        return { state: { searching: false } };
      case "search": {
        const typed = value != null && String(value).trim() ? value : (state.inputs && state.inputs.q);
        const q = String(typed == null ? "" : typed).trim().slice(0, 200);
        return q ? { go: { search: { q } }, state: { searching: false } } : { state: { searching: false } };
      }
      case "refresh":
        await applyPending();
        await ensureFresh();
        return { state: { ...(await readyState(state.tab || "movies")), rev: Date.now() } };
      default:
        return {};
    }
  } catch (e) {
    try { kino.log("screenEvent " + name + " failed: " + ((e && (e.code || e.message)) || e)); } catch { /* no log */ }
    return { state: { ready: true, importing: false } };
  }
}

// ---- settings status ----

export async function settingsStatus(key) {
  if (key !== "indexStatus") return { text: "?", textEn: "?" };
  const m = catRecentIds("movies").length;
  const s = catRecentIds("series").length;
  const e = Number(sGet(CK.episodes)) || 0;
  return { text: T.es.status(m, s, e), textEn: T.en.status(m, s, e) };
}
